import bisect
class Solution:
    def countStableSubarrays(self, nums: List[int], queries: List[List[int]]) -> List[int]:
        n = len(nums)
        c = [1] * n
        for i in range(1, n):
            if nums[i] >= nums[i-1]:
                c[i] = c[i-1] + 1
        d = [i - c[i] + 1 for i in range(n)]
        P = [0] * (n + 1)
        for i in range(n):
            P[i+1] = P[i] + c[i]
        res = []
        for l, r in queries:
            t = bisect.bisect_left(d, l, l, r + 1)
            k = t - l
            res.append(k * (k + 1) // 2 + P[r+1] - P[t])
        return res

