        int n = nums.size();
        vector<int> c(n, 1), d(n);
        for (int i = 1; i < n; i++)
            if (nums[i] >= nums[i-1]) c[i] = c[i-1] + 1;
        for (int i = 0; i < n; i++) d[i] = i - c[i] + 1;
        vector<long long> P(n + 1, 0);
        for (int i = 0; i < n; i++) P[i+1] = P[i] + c[i];
        vector<long long> res;
        for (auto& q : queries) {
            int l = q[0], r = q[1];
            int t = lower_bound(d.begin() + l, d.begin() + r + 1, l) - d.begin();
            long long k = t - l;
            res.push_back(k * (k + 1) / 2 + P[r+1] - P[t]);
