class Solution {
    public long[] countStableSubarrays(int[] nums, int[][] queries) {
        int n = nums.length;
        int[] c = new int[n], d = new int[n];
        java.util.Arrays.fill(c, 1);
        for (int i = 1; i < n; i++)
            if (nums[i] >= nums[i-1]) c[i] = c[i-1] + 1;
        for (int i = 0; i < n; i++) d[i] = i - c[i] + 1;
        long[] P = new long[n + 1];
        for (int i = 0; i < n; i++) P[i+1] = P[i] + c[i];
        long[] res = new long[queries.length];
        for (int qi = 0; qi < queries.length; qi++) {
            int l = queries[qi][0], r = queries[qi][1];
            int t = l;
            int lo = l, hi = r;
            while (lo <= hi) {
                int mid = (lo + hi) >>> 1;
                if (d[mid] >= l) { t = mid; hi = mid - 1; } else lo = mid + 1;
            }
            long k = t - l;
            res[qi] = k * (k + 1) / 2 + P[r+1] - P[t];
        }
        return res;
    }
}

