var countStableSubarrays = function(nums, queries) {
    const n = nums.length;
    const c = new Array(n).fill(1), d = new Array(n);
    for (let i = 1; i < n; i++)
        if (nums[i] >= nums[i-1]) c[i] = c[i-1] + 1;
    for (let i = 0; i < n; i++) d[i] = i - c[i] + 1;
    const P = new Array(n + 1).fill(0);
    for (let i = 0; i < n; i++) P[i+1] = P[i] + c[i];
    return queries.map(([l, r]) => {
        let lo = l, hi = r, t = l;
        while (lo <= hi) {
            const mid = (lo + hi) >> 1;
            if (d[mid] >= l) { t = mid; hi = mid - 1; } else lo = mid + 1;
        }
        const k = t - l;
        return k * (k + 1) / 2 + P[r+1] - P[t];
    });
};
